    ok("!! THE SEARCH IS RESUMABLE goes red alone for a missing proof; a resumed search whose final weights, draws, start value, lost flights or a checkpoint differs; a proof killed at another iteration or resumed from another state; another configuration; resumes recorded wrongly; no draws; and is clean on the real pair", (() => { const mk = (f) => { const a = mkAu(); f(a.proof32); return a; }; const a = mkAu(); a.proof32 = null; const bads = [mk((p) => { p.resumed.finalWeights = w963(0.2); }), mk((p) => { p.resumed.draws = 92; }), mk((p) => { p.resumed.startTrain = 0.51; }), mk((p) => { p.resumed.lostFlights = 2; }), mk((p) => { p.resumed.checkpoints = [{ iter: 8 }, { iter: 13 }]; }), mk((p) => { p.killedAt = 7; }), mk((p) => { p.resumedFrom = 5; }), mk((p) => { p.config.iters = 24; }), mk((p) => { p.resumed.resumes = [5]; }), mk((p) => { p.straight.resumes = [4]; }), mk((p) => { p.straight.draws = 0; p.resumed.draws = 0; })]; return only(a, "THE SEARCH IS RESUMABLE") && bads.every((x) => only(x, "THE SEARCH IS RESUMABLE")); })() && (() => { const rp = JSON.parse(fs.readFileSync(new URL("../../brain/rig-results/head-to-head32-proof.json", import.meta.url), "utf8")); return reds(mkAu({}, { proof32: rp })).length === 0; })());
